sys_script_include.script:
function GetCleanPackageObject(vPackageObject)
{
	var packageobject = null;

	if (IsValidRecord(vPackageObject) == true)
	{
		packageobject = Clone(vPackageObject,true);
	}
	else
	{
		if (IsObject(vPackageObject) == false)
		{
			return false;
		}
		packageobject = vPackageObject;
	}

	delete packageobject.action;
	delete packageobject.can_edit_in_studio;
	delete packageobject.enforce_license;
	delete packageobject.guided_setup_guid;
	delete packageobject.hide_on_ui;
	delete packageobject.ide_created;
	delete packageobject.installed_as_dependency;
	delete packageobject.licensable;
	delete packageobject.license;
	delete packageobject.license_category;
	delete packageobject.license_definition;	
	delete packageobject.license_model;
	delete packageobject.logo;
	delete packageobject.menu;
	delete packageobject.private;
	delete packageobject.restrict_table_access;
	delete packageobject.runtime_access_tracking;
	delete packageobject.scoped_administration;
	delete packageobject.store_correlation_id;
	delete packageobject.store_url;	
	delete packageobject.subscription_entitlement
	delete packageobject.sys_code;	
	delete packageobject.sys_created_by;
	delete packageobject.sys_created_on;
	delete packageobject.sys_meta;
	delete packageobject.sys_mod_count;	
	delete packageobject.sys_tags;
	delete packageobject.sys_updated_by;	
	delete packageobject.sys_updated_on;
	delete packageobject.template;
	delete packageobject.trackable;
	delete packageobject.uninstall_blocked;	
	delete packageobject.user_role;	
	delete packageobject.vendor;
	delete packageobject.vendor_prefix;

	return packageobject;
}
